function orderTable(xs){return '<div class="pro-table"><table><thead><tr><th>Pesanan</th><th>Customer</th><th>Tanggal sewa</th><th>Pembayaran</th><th>Total</th></tr></thead><tbody>'+xs.map(o=>`<tr><td>${E(o.order_number)}</td><td>${E(o.customer_name)}</td><td>${E(o.start_date)} — ${E(o.end_date)}</td><td>${E(({unpaid:'Belum bayar',pending:'Menunggu cek',partial:'Sebagian',paid:'Lunas',rejected:'Ditolak'})[o.payment_status])}</td><td>${M(o.total)}</td></tr>`).join('')+'</tbody></table></div>'}
function orderForm(quote=false){const s=docSettings(),valid=new Date();valid.setDate(valid.getDate()+7);return '<div class="pro-card quotation-sheet qd-editor"><form id="proDirectForm" data-kind="'+(quote?'quotation':'direct_order')+'"><header class="qd-header"><div><div class="qd-brandline">'+(s.logo?'<img class="qd-logo" src="'+E(s.logo)+'">':'')+'<div><h2>'+E(s.company)+'</h2><small>'+E(s.legalName||s.tagline)+'</small></div></div><p>'+E(s.address).replace(/\n/g,'<br>')+'</p><p>'+E(s.email)+' · '+E(s.phone)+'</p></div><div class="qd-doc"><h1>'+E(s.quotationTitle)+'</h1><p>Nomor otomatis setelah disimpan</p><p>'+E(today())+'</p><label>Berlaku sampai<input name="valid_until" type="date" value="'+valid.toLocaleDateString('sv-SE')+'" required></label></div></header><div class="qd-info"><section><small>INFORMASI CUSTOMER</small><label class="qd-master-label">Pilih customer<select id="quotationCustomer"><option value="">Customer baru / input manual</option></select></label><p id="quotationCustomerInfo">Memuat Master Customer...</p><label>Customer / Client<input name="name" minlength="2" maxlength="120" required autocomplete="name"></label><label>Telepon<input name="phone" type="tel" required></label><label>Email<input name="email" type="email"></label></section><section><small>PERIODE RENTAL</small><label>Pengambilan<input name="start" type="date" min="'+today()+'" value="'+today()+'" required></label><label>Pengembalian<input name="end" type="date" min="'+today()+'" value="'+today()+'" required></label><div class="qd-kv"><span>Durasi</span><b id="quotationDays">1 hari</b></div><label>Program / lokasi / catatan<textarea name="notes" maxlength="2000" placeholder="Program, lokasi produksi dan kebutuhan"></textarea></label></section></div><div class="pro-table quotation-equipment qd-tablewrap"><table><colgroup><col style="width:4%"><col style="width:42%"><col style="width:8%"><col style="width:8%"><col style="width:17%"><col style="width:17%"><col style="width:4%"></colgroup><thead><tr><th></th><th aria-label="Equipment"></th><th>Qty</th><th>Hari</th><th>Harga / hari</th><th>Jumlah</th><th></th></tr></thead><tbody id="proItemRows"></tbody></table></div>'+B('add-item','+ Tambah produk')+'<div class="qd-summaryarea"><section><small>REKENING PEMBAYARAN</small><p>Rekening mengikuti pilihan pembayaran pesanan.</p><div class="qd-terms"><h4>SYARAT & KETENTUAN</h4><ol>'+s.terms.split('\n').filter(t=>t.trim()).map(t=>'<li>'+E(t)+'</li>').join('')+'</ol></div></section><section class="qd-summary"><div class="qd-kv"><span>Subtotal sebelum diskon</span><b id="quotationSubtotal">Rp0</b></div><fieldset class="quote-discount-checks"><legend>Diskon</legend><label><input type="radio" name="discount_mode" value="none" checked> Tanpa diskon</label><label><input type="radio" name="discount_mode" value="product"> Per produk</label><label><input type="radio" name="discount_mode" value="days"> Hari bayar</label></fieldset><label data-free-days hidden>Hari gratis<input name="free_days" type="number" min="0" value="0"></label><div class="qd-kv"><span>Diskon tambahan</span><b id="quoteDiscountValue">Rp0</b></div><div class="qd-kv"><span>Estimasi total</span><b id="quoteFinalValue">Rp0</b></div><p>Diskon tambahan diterapkan setelah promo katalog. Total final tersimpan dihitung server.</p></section></div><div class="qd-signs"><div>Disetujui oleh<div class="quote-signature-box"><canvas id="quoteSignature" width="420" height="130"></canvas><span>Tanda tangan di area ini</span><button type="button" data-sign-clear>Hapus</button></div><strong>'+E(s.signatory||'________________')+'</strong>'+E(s.company)+'</div><div>Customer<strong>________________</strong>Client</div></div><footer>'+E(s.footer)+'</footer><div class="quotation-bottom"><p>Konfirmasi stok dan pembayaran diperlukan sebelum rental disetujui.</p><button type="submit">'+(quote?'Simpan penawaran':'Simpan pesanan & quotation')+'</button></div><p data-msg role="status"></p></form></div>'}

function quotePrice(p){if(!p)return 0;const cfg=window.RENTCAM_CMS_CONFIG||{},x={...(cfg.customProducts||[]).find(x=>x.id===p.id),...cfg.productOverrides?.[p.id]},t=today(),discount=Number(x.discountPercent||0),active=(!x.discountStart||x.discountStart<=t)&&(!x.discountEnd||x.discountEnd>=t);return Math.round(Number(p.price||0)*(active?1-Math.max(0,Math.min(100,discount))/100:1))}
function pickerProduct(p){const cfg=window.RENTCAM_CMS_CONFIG||{},base=(cfg.customProducts||[]).find(x=>x.id===p.id)||{},o=cfg.productOverrides?.[p.id]||{},x={...base,...o};return {...p,image:x.images?.[0]||x.image||'',category:(cfg.mainCategories||[]).find(c=>c.id===x.mainCategory)?.name||x.category||'Equipment',brand:x.brand||p.brand||''}}
function productPicker(){document.querySelector('#quotePicker')?.remove();const n=document.createElement('div');n.id='quotePicker';n.innerHTML='<div class="qp-panel"><header><div><h2>Tambah equipment</h2><p>Pilih beberapa produk dari master data. Klik Tambah untuk memasukkannya ke penawaran.</p></div><button data-qp-close>×</button></header><div class="qp-search"><input id="qpSearch" placeholder="Cari produk atau brand…"><select id="qpCategory"><option value="">Semua kategori</option>'+[...new Set(stock.map(p=>pickerProduct(p).category))].sort().map(c=>'<option>'+E(c)+'</option>').join('')+'</select></div><div id="qpGrid"></div><footer><span id="qpCount"></span><button data-qp-done>Selesai memilih</button></footer></div>';document.body.append(n);pickerRender();n.querySelector('#qpSearch').focus()}
function pickerRender(){const n=document.querySelector('#quotePicker');if(!n)return;const q=n.querySelector('#qpSearch').value.toLowerCase(),cat=n.querySelector('#qpCategory').value,rows=[...document.querySelectorAll('.pro-item-row')];n.querySelector('#qpCount').textContent=rows.length+' produk di penawaran';n.querySelector('#qpGrid').innerHTML=stock.map(pickerProduct).filter(p=>(!cat||p.category===cat)&&(p.name+' '+p.brand).toLowerCase().includes(q)).map(p=>{const row=rows.find(r=>r.querySelector('[data-item]').value===p.id),qty=row?.querySelector('[data-quantity]').value||0;return '<article><div class="qp-image">'+(p.image?'<img src="'+E(p.image)+'" loading="lazy">':'<span>Equipment</span>')+'</div><small>'+E(p.category)+' · '+E(p.brand)+'</small><h3>'+E(p.name)+'</h3><b>'+M(p.price)+' / hari</b><p>'+p.available+' unit tersedia · '+qty+' dipilih</p><button data-qp-add="'+E(p.id)+'">+ Tambah</button></article>'}).join('')||'<p>Produk tidak ditemukan.</p>'}
document.addEventListener('click',e=>{const n=document.querySelector('#quotePicker');if(!n)return;if(e.target===n||e.target.closest('[data-qp-close],[data-qp-done]')){n.remove();return}const b=e.target.closest('[data-qp-add]');if(b){const id=b.dataset.qpAdd,rows=[...document.querySelectorAll('.pro-item-row')],existing=rows.find(r=>r.querySelector('[data-item]').value===id);if(existing){const qty=existing.querySelector('[data-quantity]');qty.value=Math.min(100,Number(qty.value)+1)}else{addItem();document.querySelector('#proItemRows .pro-item-row:last-child [data-item]').value=id}estimate();pickerRender()}},true);
document.addEventListener('input',e=>{if(e.target.id==='qpSearch')pickerRender()});document.addEventListener('change',e=>{if(e.target.id==='qpCategory')pickerRender()});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('#quotePicker')?.remove()});

let quoteSignDirty=false;
function setupSignature(){const c=document.querySelector('#quoteSignature');if(!c||c.dataset.ready)return;c.dataset.ready='1';const x=c.getContext('2d');x.lineWidth=2.2;x.lineCap='round';x.strokeStyle='#222';let draw=false;const point=e=>{const r=c.getBoundingClientRect(),p=e.touches?.[0]||e;return[(p.clientX-r.left)*c.width/r.width,(p.clientY-r.top)*c.height/r.height]};c.addEventListener('pointerdown',e=>{draw=true;quoteSignDirty=true;const[a,b]=point(e);x.beginPath();x.moveTo(a,b);e.preventDefault()});c.addEventListener('pointermove',e=>{if(!draw)return;const[a,b]=point(e);x.lineTo(a,b);x.stroke();e.preventDefault()});addEventListener('pointerup',()=>draw=false)}
async function uploadAdminBlob(blob,folder,ext){const token=await rpc('rentcam_issue_upload_token',{}),path=encodeURIComponent(String(token).replace(/"/g,''))+'/'+folder+'/'+crypto.randomUUID()+'.'+ext,r=await fetch(SB+'/storage/v1/object/cms-media/'+path,{method:'POST',headers:{apikey:KEY,'Content-Type':blob.type},body:blob});if(!r.ok)throw Error('Upload file gagal');return SB+'/storage/v1/object/public/cms-media/'+path}
async function signatureUrl(){if(!quoteSignDirty)return '';const c=document.querySelector('#quoteSignature'),blob=await new Promise(r=>c.toBlob(r,'image/png'));return uploadAdminBlob(blob,'document-signatures','png')}
async function loadPdf(){if(window.html2pdf)return;await new Promise((ok,no)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/html2pdf.js@0.10.2/dist/html2pdf.bundle.min.js';s.onload=ok;s.onerror=()=>no(Error('Pembuat PDF gagal dimuat'));document.head.append(s)})}
async function makePdf(d){await loadPdf();const filename=(d.kind==='invoice'?'Invoice-':'Quotation-')+d.number.replace(/[^\w-]+/g,'-')+'.pdf',worker=window.html2pdf().set({margin:[8,8],filename,image:{type:'jpeg',quality:.96},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(document.querySelector('#proPrintable')).toPdf();return{blob:await worker.output('blob'),filename}}

let quotationCustomers=[];
async function loadCustomers(){const picker=document.querySelector('#quotationCustomer');if(!picker)return;try{quotationCustomers=await api('rentcam_contacts?select=*&kind=eq.customer&order=name.asc');const phoneKey=p=>String(p||'').replace(/\D/g,'').replace(/^62/,'0'),known=new Set(quotationCustomers.map(c=>phoneKey(c.phone)).filter(Boolean));orders.filter(o=>o.source!=='quotation'&&o.rental_status!=='cancelled').forEach(o=>{const key=phoneKey(o.phone);if(key&&!known.has(key)){known.add(key);quotationCustomers.push({id:'order-'+o.id,name:o.customer_name,phone:o.phone,email:o.email,company:''})}});if(!picker.isConnected)return;picker.innerHTML='<option value="">Customer baru / input manual</option>'+quotationCustomers.map(c=>`<option value="${E(c.id)}">${E(c.name)}${c.company?' · '+E(c.company):''}${c.phone?' · '+E(c.phone):''}</option>`).join('');document.querySelector('#quotationCustomerInfo').textContent=quotationCustomers.length+' customer dari Master Data. Pilih untuk mengisi kontak otomatis.'}catch(e){if(picker.isConnected)document.querySelector('#quotationCustomerInfo').textContent=e.message}}
async function loadProducts(){const f=document.querySelector('#proDirectForm');if(!f)return;try{const data=await rpc('rentcam_admin_stock',{p_start:f.elements.start.value,p_end:f.elements.end.value,p_exclude:null});if(!f.isConnected)return;stock=data;f.querySelectorAll('[data-item]').forEach(select=>{const value=select.value;select.innerHTML='<option value="">Pilih produk dari master</option>'+stock.map(p=>'<option value="'+E(p.id)+'">'+E(p.name)+' · tersedia '+p.available+'</option>').join('');select.value=value});estimate()}catch(e){f.querySelector('[data-msg]').textContent=e.message}}function addItem(){document.querySelector('#proItemRows')?.insertAdjacentHTML('beforeend',`<tr class="pro-item-row"><td data-row-number></td><td><select data-item required><option value="">Pilih produk dari master</option>${stock.map(p=>`<option value="${E(p.id)}">${E(p.name)} · tersedia ${p.available}</option>`).join('')}</select></td><td><input data-quantity type="number" min="1" max="100" value="1" required aria-label="Jumlah produk"></td><td data-row-days>1</td><td data-row-price>Rp0</td><td><strong data-row-amount>Rp0</strong><label class="quote-item-discount" hidden>Diskon %<input data-item-discount type="number" min="0" max="100" value="0"></label></td><td>${B('remove-item','×')}</td></tr>`);estimate()}
function estimate(){setupSignature();const f=document.querySelector('#proDirectForm');if(!f)return;const days=Math.max(0,Math.round((new Date(f.elements.end.value)-new Date(f.elements.start.value))/86400000)+1),rows=[...f.querySelectorAll('.pro-item-row')];let subtotal=0,finalTotal=0;const discountMode=f.elements.discount_mode.value,freeDays=Number(f.elements.free_days.value||0);f.querySelector('[data-free-days]').hidden=discountMode!=='days';f.elements.free_days.max=days;rows.forEach((r,i)=>{const p=stock.find(p=>p.id===r.querySelector('[data-item]').value),price=quotePrice(p),qty=Number(r.querySelector('[data-quantity]').value||0),amount=price*qty*days;subtotal+=amount;const percent=discountMode==='product'?Number(r.querySelector('[data-item-discount]').value||0):0,charged=discountMode==='days'?Math.max(0,days-freeDays):days,finalAmount=Math.round(price*qty*charged*(1-percent/100));finalTotal+=finalAmount;r.querySelector('.quote-item-discount').hidden=discountMode!=='product';r.querySelector('[data-row-number]').textContent=i+1;r.querySelector('[data-row-days]').textContent=days;r.querySelector('[data-row-price]').textContent=M(price);r.querySelector('[data-row-amount]').textContent=M(finalAmount)});f.querySelectorAll('[data-editor-category]').forEach(x=>x.remove());let previous='';rows.forEach(r=>{const id=r.querySelector('[data-item]').value;if(!id)return;const cfg=window.RENTCAM_CMS_CONFIG||{},p={...(cfg.customProducts||[]).find(x=>x.id===id),...cfg.productOverrides?.[id]},cat=(cfg.mainCategories||[]).find(c=>c.id===p.mainCategory)?.name||p.category||'Equipment Rental';if(cat!==previous){r.insertAdjacentHTML('beforebegin','<tr class="qd-category" data-editor-category><td colspan="7">'+E(cat)+'</td></tr>');previous=cat}});f.querySelector('#quotationDays').textContent=days+' hari';f.querySelector('#quotationSubtotal').textContent=M(subtotal);f.querySelector('#quoteDiscountValue').textContent=M(subtotal-finalTotal);f.querySelector('#quoteFinalValue').textContent=M(finalTotal)}

